"""Tests: directory layout, report accounting, and predicate-pushdown behavior."""

from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

import pyarrow as pa
import pyarrow.dataset as ds
import pytest

from generate_data import COUNTRIES, TOTAL_ROWS, YEARS

PROJECT = Path(__file__).resolve().parent
DATASET_ROOT = PROJECT.parent / "analytics_dataset"
REPORT_PATH = PROJECT.parent / "report.json"


@pytest.fixture(scope="session")
def dataset():
    if not DATASET_ROOT.exists():
        subprocess.run(
            [sys.executable, str(PROJECT / "generate_data.py")],
            check=True,
            cwd=PROJECT,
        )
    return ds.dataset(DATASET_ROOT, format="parquet", partitioning="hive")


def _report() -> dict:
    if not REPORT_PATH.exists():
        subprocess.run(
            [sys.executable, str(PROJECT / "partition_report.py"), str(DATASET_ROOT)],
            check=True,
            cwd=PROJECT,
        )
    return json.loads(REPORT_PATH.read_text())


@pytest.fixture(scope="session", autouse=True)
def report(dataset):
    return _report()


# ---------------------------------------------------------------- layout


def test_layout_has_12_leaf_partitions():
    leaves = sorted(p for p in DATASET_ROOT.glob("country=*/year=*") if p.is_dir())
    assert len(leaves) == 12
    expected = {f"country={c}/year={y}" for c in COUNTRIES for y in YEARS}
    assert {str(p.relative_to(DATASET_ROOT)) for p in leaves} == expected


def test_layout_is_hive_two_level_with_only_parquet_leaves():
    for country_dir in sorted(DATASET_ROOT.glob("country=*")):
        children = list(country_dir.iterdir())
        # exactly three year partitions per country, nothing deeper
        assert sorted(p.name for p in children) == [f"year={y}" for y in YEARS]
        for leaf in children:
            assert leaf.is_dir()
            assert {f.suffix for f in leaf.iterdir()} == {".parquet"}


def test_us_2024_is_the_biggest_slice(report):
    rows = {(p["country"], p["year"]): p["row_count"] for p in report["partitions"]}
    assert max(rows, key=rows.get) == ("US", 2024)
    assert rows[("US", 2024)] > 2 * rows[("US", 2022)]


# ------------------------------------------------------- report accounting


def test_report_row_counts_sum_to_60k(report):
    assert len(report["partitions"]) == 12
    assert sum(p["row_count"] for p in report["partitions"]) == TOTAL_ROWS
    assert report["total_rows"] == TOTAL_ROWS


def test_report_matches_per_partition_reads(dataset, report):
    for entry in report["partitions"]:
        leaf_dir = DATASET_ROOT / f"country={entry['country']}" / f"year={entry['year']}"
        files = sorted(leaf_dir.glob("*.parquet"))

        assert len(files) == entry["file_count"]
        assert sum(f.stat().st_size for f in files) == entry["total_bytes"]

        part_ds = ds.dataset(leaf_dir, format="parquet")
        assert part_ds.count_rows() == entry["row_count"]


def test_report_covers_every_partition_exactly_once(report):
    seen = [(p["country"], p["year"]) for p in report["partitions"]]
    assert len(seen) == len(set(seen)) == 12
    assert set(seen) == {(c, y) for c in COUNTRIES for y in YEARS}


# ------------------------------------------------------------ pushdown


def _fragment_relpaths(fragments) -> set[str]:
    return {Path(str(f.path)).relative_to(DATASET_ROOT).as_posix() for f in fragments}


def test_pushdown_de_2023_yields_fragments_only_under_de_2023(dataset):
    flt = (ds.field("country") == "DE") & (ds.field("year") == 2023)
    frag_paths = _fragment_relpaths(dataset.get_fragments(filter=flt))

    assert frag_paths, "pushdown scan yielded no fragments"
    expected_leaf = f"country=DE/year=2023"
    for rel in frag_paths:
        parts = rel.split("/")
        assert parts[:2] == ["country=DE", "year=2023"], rel

    on_disk = {
        f"country=DE/year=2023/{f.name}" for f in (DATASET_ROOT / "country=DE/year=2023").glob("*.parquet")
    }
    assert frag_paths == on_disk


def test_pushdown_de_2023_returns_correct_full_result(dataset):
    flt = (ds.field("country") == "DE") & (ds.field("year") == 2023)
    pushed = ds.Scanner.from_dataset(dataset, filter=flt).to_table()

    assert set(pushed["country"].unique().to_pylist()) == {"DE"}
    assert set(pushed["year"].unique().to_pylist()) == {2023}

    full = ds.Scanner.from_dataset(dataset).to_table()
    reference = full.filter(flt).combine_chunks()
    assert pushed.num_rows == reference.num_rows
    assert pushed.sort_by("user_id").select(["user_id"]).equals(
        reference.sort_by("user_id").select(["user_id"])
    )


def test_single_country_filter_prunes_to_three_year_leaves(dataset):
    frag_paths = _fragment_relpaths(dataset.get_fragments(filter=ds.field("country") == "JP"))
    assert {p.split("/")[0] for p in frag_paths} == {"country=JP"}
    assert {p.split("/")[1] for p in frag_paths} == {"year=2022", "year=2023", "year=2024"}
    assert all(len(p.split("/")) == 3 for p in frag_paths)


def test_non_partition_filter_touches_all_fragments_but_returns_correct_rows(dataset):
    n_files_on_disk = sum(len(list(d.glob("*.parquet"))) for d in DATASET_ROOT.glob("country=*/year=*"))
    all_frag_paths = _fragment_relpaths(dataset.get_fragments())

    # A predicate on a non-partition column (page_views) cannot be resolved
    # from hive keys alone: no pruning is possible, so fragment discovery
    # must touch every file in the tree.
    flt = ds.field("page_views") > 40
    touched = _fragment_relpaths(dataset.get_fragments(filter=flt))
    assert len(touched) == n_files_on_disk == 12
    assert touched == all_frag_paths

    # ...and the result must be identical to filtering the unpruned full scan.
    result = ds.Scanner.from_dataset(dataset, filter=flt).to_table()
    full = ds.Scanner.from_dataset(dataset).to_table()
    reference = full.filter(flt)

    assert result.num_rows == reference.num_rows > 0
    assert result.select(["user_id"]).sort_by("user_id").equals(
        reference.select(["user_id"]).sort_by("user_id")
    )

